#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tsato\nkaede\t2026-01-01\t13:00\t14:00\tito\nsakura\t2026-01-01\t15:00\t16:00\tsatoh\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01)" = 'reminder to sato: aoi 2026-01-01 10:00-11:00' ] || { echo "remind --who"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
err=$(bash src/remind.sh --who 2>&1 >/dev/null); [ $? = 2 ] || { echo "--who without a name and date should exit 2"; fail=1; }
[ "$err" = 'usage: remind.sh [--who NAME] DATE' ] || { echo "--who without a name: usage message is wrong: $err"; fail=1; }
bash src/remind.sh --who sato >/dev/null 2>&1; [ $? = 2 ] || { echo "--who with a name but no date should exit 2"; fail=1; }
bash src/remind.sh --who '' 2026-01-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "--who with an empty name should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01 | wc -l)" = 1 ] || { echo "--who matched a longer name"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh --who sat 2026-01-01)" = '' ] || { echo "--who matched a partial name"; fail=1; }
out=$(BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01); rc=$?
[ $rc = 0 ] && [ -z "$out" ] || { echo "--who with no reservation should exit 0 with no output"; fail=1; }
rm -f "$t"; exit $fail

